Given an integer array arr[], build a Max Heap from the given array. A Max Heap is a complete binary tree where each parent node is greater than or equal to its children, ensuring the largest element is at the root.Examples: Input: arr[] = [4, 10, 3, 5, 1]Output: Corresponding Max-Heap: Input: arr[] = [1, 3, 5, 4, 6, 13, 10, 9, 8, 15, 17]Output: Corresponding Max-Heap: [Approach] Using Recursion - O(n) Time and O(log n) Space To build a Max Heap from an array, treat the array as a complete binary tree and heapify nodes from the last non-leaf node up to the root in reverse level order. Leaf nodes already satisfy the heap property, so we start from the last non-leaf node, and for each subtree, we compare the parent with its children. Whenever a child node is greater than the parent, we swap them and continue heapifying that subtree to ensure the Max Heap property is maintained throughout.Note :Root is at index 0.Left child of node i -> 2*i + 1.Right child of node i -> 2*i + 2.Parent of node i -> (i-1)/2.Last non-leaf node -> parent of last node -> (n/2) - 1.
            C++

    #include <iostream>
#include<vector>
using namespace std;

// To heapify a subtree 
void heapify(vector<int>&arr, int n, int i)
{
    // Initialize largest as root
    int largest = i; 
    int l = 2 * i + 1; 
    int r = 2 * i + 2; 

    // If left child is larger than root
    if (l < n && arr[l] > arr[largest])
        largest = l;

    // If right child is larger than largest so far
    if (r < n && arr[r] > arr[largest])
        largest = r;

    // If largest is not root
    if (largest != i) {
        swap(arr[i], arr[largest]);

        // Recursively heapify the affected sub-tree
        heapify(arr, n, largest);
    }
}

// Function to build a Max-Heap from the given array
void buildHeap(vector<int>&arr)
{
    int n=arr.size();
    // Index of last non-leaf node

    int startIdx = (n / 2) - 1;

    // Perform reverse level order traversal
    // from last non-leaf node and heapify
    // each node
    for (int i = startIdx; i >= 0; i--) {
        heapify(arr, n, i);
    }
}

int main()
{
    // Binary Tree Representation
    // of input array
    //             1
    //           /    \
    //         3        5
    //       /  \     /  \
    //     4      6  13  10
    //    / \    / \
    //   9   8  15 17
    vector<int>arr = {1, 3, 5, 4, 6, 13, 10, 9, 8, 15, 17};

    // Function call
    buildHeap(arr);
     for (int i = 0; i < arr.size(); ++i)
        cout << arr[i] << " ";
    cout << "\n";

    // Final Heap:
    //              17
    //            /    \
    //          15      13
    //         /  \     / \
    //        9     6  5   10
    //       / \   / \
    //      4   8 3   1

    return 0;
}


